def enrich(o: Order): IO[Order] =
  customerClient.find(o.customerId)
    .map(c => o.copy(customerName = Some(c.name), region = Some(c.region)))
    .timeout(2.seconds)
    .handleErrorWith(_ => IO.pure(o))          // degrade, but log/metric the failure

def enrichAll(os: List[Order]): IO[List[Order]] = os.parTraverse(enrich)
